<?php
namespace Modules\BankingCheque\Http\Controllers;
use Illuminate\Routing\Controller; use Illuminate\Http\Request; use Modules\BankingCheque\Entities\ChequeStopPayment;
class StopPaymentController extends Controller { public function index(){ $stops=ChequeStopPayment::latest()->paginate(25); return view('bankingcheque::stop_payments.index',compact('stops')); } public function create(){ return view('bankingcheque::stop_payments.create'); } public function store(Request $r){ ChequeStopPayment::create($r->all()+['status'=>'pending']); return redirect()->route('banking.cheques.stop-payments.index'); } public function show(ChequeStopPayment $stop_payment){ return view('bankingcheque::stop_payments.show',['stop'=>$stop_payment]); } public function edit(ChequeStopPayment $stop_payment){ return view('bankingcheque::stop_payments.edit',['stop'=>$stop_payment]); } public function update(Request $r, ChequeStopPayment $stop_payment){ $stop_payment->update($r->all()); return back(); } public function destroy(ChequeStopPayment $stop_payment){ $stop_payment->delete(); return back(); } }
